insert into private.nr_topics(id,title,hint,min_players,max_players) values
('provincias_es','Provincias de España','Las 50 provincias españolas; se aceptan nombres en lenguas cooficiales.',2,8),
('autonomias_es','Comunidades autónomas españolas','Las 17 comunidades autónomas. Ceuta y Melilla son ciudades autónomas, no cuentan.',2,3),
('pokemon_kanto','Pokémon de la primera generación','Los 151 Pokémon de la Pokédex de Kanto. Nidoran macho y hembra cuentan por separado.',2,12),
('campeones_mundial','Selecciones campeonas del Mundial de fútbol masculino','Países que han ganado alguna Copa Mundial masculina de la FIFA.',2,2),
('star_wars','Películas de la saga principal de Star Wars','Solo los episodios I–IX. No cuentan series ni películas derivadas.',2,2),
('marcas_coches','Marcas de automóviles','Marcas de coches comerciales (actuales o históricas), no modelos.',2,10),
('instrumentos','Instrumentos musicales','Instrumentos de cualquier familia: cuerda, viento, percusión o electrónicos.',2,10) on conflict (id) do update set title=excluded.title,hint=excluded.hint,min_players=excluded.min_players,max_players=excluded.max_players;
